    cl_kernel kernel_gemm_noshuffle_q5_k_q8_1_dp4a_act_vload4 = शून्यसूचकः;
    cl_kernel kernel_gemm_noshuffle_q6_k_q8_1_dp4a = शून्यसूचकः;  // dp4a (int8) dense q6_K prefill GEMM
