        CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel,  1, परिमाण(cl_ulong), &offset0));
        CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel,  2, परिमाण(cl_mem),   &extra1->दत्त_device));
        CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel,  3, परिमाण(cl_ulong), &offset1));
        CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel,  4, परिमाण(cl_mem),   &extrad->दत्त_device));
        CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel,  5, परिमाण(cl_ulong), &offsetd));
        CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel,  6, परिमाण(cl_ulong), &nb00));
        CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel,  7, परिमाण(cl_ulong), &nb01));
        CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel,  8, परिमाण(cl_ulong), &nb02));
        CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel,  9, परिमाण(cl_ulong), &nb03));
        CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, 10, परिमाण(पूर्णाङ्क),      &ne10));
        CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, 11, परिमाण(पूर्णाङ्क),      &ne11));
        CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, 12, परिमाण(पूर्णाङ्क),      &ne12));
        CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, 13, परिमाण(पूर्णाङ्क),      &ne13));
        CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, 14, परिमाण(cl_ulong), &nb10));
