                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, k_arg++, परिमाण(पूर्णाङ्क),      &ne11));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, k_arg++, परिमाण(पूर्णाङ्क),      &ne12));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, k_arg++, परिमाण(cl_ulong), &nb10));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, k_arg++, परिमाण(cl_ulong), &nb11));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, k_arg++, परिमाण(cl_ulong), &nb12));
