                    // Create sub buffer for dst
                    region.origin = offsetd;
                    region.size = ne0 * ne1 * ne2 * परिमाण(भिन्न);
                    sub_buf_dst = cl_Create_Sub_बफर(
                        extrad->दत्त_device,
                        0,
                        CL_बफर_CREATE_TYPE_REGION,
                        &region,
                        &स्थितिः);
                    CL_CHECK(स्थितिः);
                    // Create image for dst
                    cl_image_format image_format_buf_dst = {CL_R, CL_FLOAT};
                    cl_image_desc image_desc_buf_dst = {CL_MEM_OBJECT_IMAGE1_D_बफर, static_cast<size_t>(ne0 * ne1 * ne2), 0,0,0,0,0,0,0, {sub_buf_dst}};
                    buf_dst_image = clCreateImage(backend_ctx->context, CL_MEM_WRITE_ONLY, &image_format_buf_dst, &image_desc_buf_dst, रिक्त, &स्थितिः);
                    CL_CHECK(स्थितिः);

                    // Set kernel args
                    पूर्णाङ्क arg_idx = 0;
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem),    &extra0_q5_1->qs_img));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem),    &extra0_q5_1->qh));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem),    &extra0_q5_1->d));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem),    &extra0_q5_1->m));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem),    &image_src1_reordered));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem),    &buf_src2));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem),    &buf_src2_emap));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem),    &buf_dst_image));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem),    &(backend_ctx->prealloc_योग_tiles.बफर)));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(पूर्णाङ्क),       &ne00));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(पूर्णाङ्क),       &ne01));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_uint),       &backend_ctx->adreno_use_moe_ragged));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_uint),       &backend_ctx->adreno_moe_ragged_skip_gran));

                    // set thread grid
                    global_आकार[1] = static_cast<size_t>((ne01 + 63) / 64);
                    global_आकार[2] = static_cast<size_t>(max_post_मार्गदर्शकः_tile);
                    local_आकार[1] = 1;
                    local_आकार[2] = 1;

                    // Dispatch kernel
                    backend_ctx->पङ्क्तौ_निक्षिप_ndrange_kernel(kernel, 3, global_आकार, local_आकार, dst);

                    clReleaseMemObject(sub_buf_src1_pre);
                    clReleaseMemObject(buf_src1_reordered);
                    clReleaseMemObject(image_src1_reordered);
                    clReleaseMemObject(buf_src2);
                    clReleaseMemObject(buf_src2_emap);
                    clReleaseMemObject(sub_buf_dst);
                    clReleaseMemObject(buf_dst_image);
