                        CL_CHECK(cl_समुच्चयः_Kernel_Arg(rq, 2, परिमाण(cl_mem),         &backend_ctx->prealloc_moe_qa.बफर));
                        CL_CHECK(cl_समुच्चयः_Kernel_Arg(rq, 3, परिमाण(cl_mem),         &backend_ctx->prealloc_moe_da.बफर));
                        CL_CHECK(cl_समुच्चयः_Kernel_Arg(rq, 4, परिमाण(cl_mem),         &backend_ctx->prealloc_moe_sa.बफर));
                        CL_CHECK(cl_समुच्चयः_Kernel_Arg(rq, 5, परिमाण(cl_mem),         &(backend_ctx->prealloc_योग_tiles.बफर)));
                        CL_CHECK(cl_समुच्चयः_Kernel_Arg(rq, 6, परिमाण(cl_uint),        &ne00));
