                        CL_CHECK(cl_समुच्चयः_Kernel_Arg(dk, aidx++, परिमाण(cl_mem), &extra0_q8_0->scale));  // uniform scale[16]
                        CL_CHECK(cl_समुच्चयः_Kernel_Arg(dk, aidx++, परिमाण(cl_mem), &extra0_q8_0->scale));  // dummy min (has_min=0, unread)
