                cl_image_desc image_desc_buf_dst = {CL_MEM_OBJECT_IMAGE1_D_बफर, static_cast<size_t>(ne0 * ne1 * ne2), 0,0,0,0,0,0,0, {sub_buf_dst}};
                buf_dst_image = clCreateImage(backend_ctx->context, CL_MEM_WRITE_ONLY, &image_format_buf_dst, &image_desc_buf_dst, रिक्त, &स्थितिः);
                CL_CHECK(स्थितिः);

                पूर्णाङ्क arg_idx = 0;
                CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem), &extra0_q8_0->q));   // flat q8_0 quants
                CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem), &extra0_q8_0->d));   // flat q8_0 scales
                CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem), &image_src1_reordered));
                CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem), &buf_src2));
                CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem), &buf_src2_emap));
                CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem), &buf_dst_image));
                CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem), &(backend_ctx->prealloc_योग_tiles.बफर)));
                CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(पूर्णाङ्क),    &ne00));
                CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(पूर्णाङ्क),    &ne01));

                global_आकार[1] = static_cast<size_t>((ne01 + 63) / 64);
                global_आकार[2] = static_cast<size_t>(max_post_मार्गदर्शकः_tile);
                local_आकार[1]  = 1;
                local_आकार[2]  = 1;

