                        पूर्णाङ्क aidx = 0;
                        CL_CHECK(cl_समुच्चयः_Kernel_Arg(dk, aidx++, परिमाण(cl_mem), &extra0_q4_K->q_img));
                        CL_CHECK(cl_समुच्चयः_Kernel_Arg(dk, aidx++, परिमाण(cl_mem), &extra0_q4_K->d));
