                        CL_CHECK(cl_समुच्चयः_Kernel_Arg(dk, aidx++, परिमाण(cl_mem), &backend_ctx->prealloc_moe_da.बफर));
                        CL_CHECK(cl_समुच्चयः_Kernel_Arg(dk, aidx++, परिमाण(cl_mem), &backend_ctx->prealloc_moe_sa.बफर));
                        CL_CHECK(cl_समुच्चयः_Kernel_Arg(dk, aidx++, परिमाण(cl_mem), &buf_src2));
                        CL_CHECK(cl_समुच्चयः_Kernel_Arg(dk, aidx++, परिमाण(cl_mem), &buf_src2_emap));
                        CL_CHECK(cl_समुच्चयः_Kernel_Arg(dk, aidx++, परिमाण(cl_mem), &buf_dst_image));
                        CL_CHECK(cl_समुच्चयः_Kernel_Arg(dk, aidx++, परिमाण(cl_mem), &(backend_ctx->prealloc_योग_tiles.बफर)));
                        CL_CHECK(cl_समुच्चयः_Kernel_Arg(dk, aidx++, परिमाण(पूर्णाङ्क),    &ne00));
                        CL_CHECK(cl_समुच्चयः_Kernel_Arg(dk, aidx++, परिमाण(पूर्णाङ्क),    &ne01));
                        CL_CHECK(cl_समुच्चयः_Kernel_Arg(dk, aidx++, परिमाण(पूर्णाङ्क),    &backend_ctx->adreno_use_moe_ragged_dp4));

                        size_t dp_global[3] = { 64, (size_t)((ne01 + 63) / 64), (size_t)max_post_मार्गदर्शकः_tile };
                        size_t dp_local[3]  = { 64, 1, 1 };
                        backend_ctx->पङ्क्तौ_निक्षिप_ndrange_kernel(dk, 3, dp_global, dp_local, dst);

                        clReleaseMemObject(sub_buf_src1_pre);
                        clReleaseMemObject(buf_src2);
                        clReleaseMemObject(buf_src2_emap);
