                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem),    &extra0_q4_K->d));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem),    &extra0_q4_K->dm));
