                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem),    &buf_dst_image));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem),    &(backend_ctx->prealloc_योग_tiles.बफर)));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(पूर्णाङ्क),       &ne00));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(पूर्णाङ्क),       &ne01));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_uint),   &backend_ctx->adreno_use_moe_ragged));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_uint),   &backend_ctx->adreno_moe_ragged_skip_gran));

