                    global_आकार[1] = static_cast<size_t>((ne01 + 63) / 64);
                    global_आकार[2] = static_cast<size_t>(max_post_मार्गदर्शकः_tile);
                    local_आकार[1] = 1;
                    local_आकार[2] = 1;

                    // Dispatch kernel
                    backend_ctx->पङ्क्तौ_निक्षिप_ndrange_kernel(kernel, 3, global_आकार, local_आकार, dst);

