                    buf_src1_image = clCreateImage(backend_ctx->context, CL_MEM_READ_ONLY, &image_format_buf_src1, &image_desc_buf_src1, रिक्त, &स्थितिः);
                    CL_CHECK(स्थितिः);

                    // Set kernel args
                    पूर्णाङ्क arg_idx = 0;
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem),    &extra0_q5_K->q));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem),    &extra0_q5_K->qh));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(cl_mem),    &extra0_q5_K->d));
