                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(पूर्णाङ्क),       &ne00));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(पूर्णाङ्क),       &ne01));
                    CL_CHECK(cl_समुच्चयः_Kernel_Arg(kernel, arg_idx++, परिमाण(पूर्णाङ्क),       &ne11));

