                    buf_src2 = cl_Create_Sub_बफर(backend_ctx->prealloc_post_मार्गदर्शकः.बफर, 0, CL_बफर_CREATE_TYPE_REGION, &region, &स्थितिः);
                    CL_CHECK(स्थितिः);

                    region.origin = 0;
                    region.size = परिमाण(ह्रस्व) * max_post_मार्गदर्शकः_tile;
