                            size_t rq_local[2]  = { 32, 1 };
                            size_t rq_global[2] = { (size_t)(((n_kblocks + 31) / 32) * 32), tok_slots };
                            backend_ctx->पङ्क्तौ_निक्षिप_ndrange_kernel(rq, 2, rq_global, rq_local, dst);

