                            CL_CHECK(cl_समुच्चयः_Kernel_Arg(dk, aidx++, परिमाण(cl_mem), &extra0_q5_K->qh));
                            CL_CHECK(cl_समुच्चयः_Kernel_Arg(dk, aidx++, परिमाण(cl_mem), &extra0_q5_K->scale));
                            CL_CHECK(cl_समुच्चयः_Kernel_Arg(dk, aidx++, परिमाण(cl_mem), &extra0_q5_K->min));
                            CL_CHECK(cl_समुच्चयः_Kernel_Arg(dk, aidx++, परिमाण(cl_mem), &backend_ctx->prealloc_moe_qa.बफर));
                            CL_CHECK(cl_समुच्चयः_Kernel_Arg(dk, aidx++, परिमाण(cl_mem), &backend_ctx->prealloc_moe_da.बफर));
